{{-- SphereSeam editor: shared by the full admin page (index) and the Home tool frame (frame). --}}
    @include('dam::asset.picker-modal')
    <v-dam-asset-picker></v-dam-asset-picker>
    <v-sphere-seam></v-sphere-seam>

    @pushOnce('scripts')
        <script type="text/x-template" id="v-sphere-seam-template">
            <div class="flex min-h-[calc(100vh-96px)] flex-col gap-4">
                <header class="flex flex-wrap items-end justify-between gap-3">
                    <div><p class="text-xl font-bold text-gray-800 dark:text-white">SphereSeam</p><p class="mt-1 max-w-3xl text-sm text-gray-500 dark:text-gray-400">Prepare exact 2:1 VR panoramas locally, roll the wrap seam into a supported-ratio crop, and use Higgsfield only to repair the centre of that crop.</p></div>
                    <span class="rounded-full border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-500 dark:border-cherry-800 dark:bg-cherry-900">Native Mothership module</span>
                </header>

                <div class="grid min-h-0 flex-1 gap-4 xl:grid-cols-[330px_minmax(0,1fr)_300px]">
                    <aside class="space-y-4 rounded-xl bg-white p-4 shadow-sm dark:bg-cherry-900 xl:sticky xl:top-4 xl:h-[calc(100vh-128px)] xl:overflow-y-auto">
                        <section><p class="text-xs font-semibold uppercase tracking-wide text-gray-500">1 · Source panorama</p><div class="mt-2 grid grid-cols-2 gap-2"><label class="secondary-button flex cursor-pointer items-center justify-center gap-2 !px-2 text-xs"><span class="icon-export"></span>Local file<input type="file" accept="image/jpeg,image/png,image/webp" class="hidden" @change="chooseFile"></label><button type="button" class="secondary-button flex items-center justify-center gap-2 !px-2 text-xs" @click="openDamPicker"><span class="icon-dam"></span>From DAM</button></div><p v-if="sourceName" class="mt-2 truncate text-xs text-gray-500" v-text="sourceName"></p></section>
                        <section class="space-y-3 border-t border-gray-100 pt-4 dark:border-cherry-800"><p class="text-xs font-semibold uppercase tracking-wide text-gray-500">2 · Local geometry</p>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Make exact 2:1 by</span><select v-model="normalization" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="squeeze">Squeeze the long axis (default)</option><option value="pad">Pad with bands</option></select></label>
                            <label v-if="normalization === 'pad'" class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Padding fill</span><select v-model="fill" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="edge">Extend edge pixels</option><option value="transparent">Transparent</option></select></label>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Repair band (centre of the seam crop)</span><select v-model="repair" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="narrow">Narrow · 25%</option><option value="balanced">Balanced · 40%</option><option value="wide">Wide · 55%</option><option value="custom">Custom pixels</option></select></label>
                            <input v-if="repair === 'custom'" v-model.number="customRepairWidth" type="number" min="16" max="8192" class="w-full rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950" placeholder="Repair band width in pixels">
                            <p class="text-[11px] leading-4 text-gray-400">The bridge is the panorama rolled so its wrap seam sits in the centre. Pixels outside the green band are restored from the original after generation; GPT Image has no mask input, so the band is a prompt instruction only.</p>
                            <p v-if="normalizationLabel" class="rounded-lg bg-gray-50 p-3 text-xs leading-5 text-gray-600 dark:bg-cherry-950 dark:text-gray-300" v-text="normalizationLabel"></p>
                        </section>
                        <section class="space-y-3 border-t border-gray-100 pt-4 dark:border-cherry-800"><p class="text-xs font-semibold uppercase tracking-wide text-gray-500">3 · Seam bridge</p>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Model</span><select v-model="model" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="gpt_image_2">GPT Image 2</option><option value="gpt_image_2_5">GPT Image 2.5</option></select></label>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Supported bridge ratio</span><select v-model="ratio" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="1:1">1:1 · widest band (default)</option><option value="3:4">3:4</option><option value="9:16">9:16 · narrow</option><option v-if="model === 'gpt_image_2_5'" value="16:27">16:27</option></select></label>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Quality</span><select v-model="quality" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="auto">Auto · best match for this image</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></label>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Resolution</span><select v-model="resolution" class="mt-1.5 w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option value="auto">Auto · best match for this image</option><option value="1k">1K</option><option value="2k">2K</option><option value="4k">4K</option></select></label>
                            <p v-if="resolvedSettingsLabel" class="text-[11px] leading-4 text-gray-400" v-text="resolvedSettingsLabel"></p>
                            <p v-if="providerOutputLabel" class="text-[11px] leading-4 text-gray-400" v-text="providerOutputLabel"></p>
                            <label class="block"><span class="text-xs text-gray-600 dark:text-gray-300">Scene context (optional)</span><textarea v-model="scene" rows="3" class="mt-1.5 w-full resize-y rounded-lg border border-gray-200 bg-gray-50 p-3 text-sm dark:border-cherry-800 dark:bg-cherry-950" placeholder="Foundry interior, warm practical light, smoke haze…"></textarea></label>
                            <div v-if="jobFeedback" class="rounded-lg border p-3 text-xs" :class="jobFeedback.tone" role="status" aria-live="polite"><div class="flex items-center gap-2"><span v-if="jobFeedback.busy" class="icon-spinner animate-spin"></span><span class="font-semibold" v-text="jobFeedback.title"></span><span v-if="jobFeedback.elapsed" class="ml-auto tabular-nums opacity-70" v-text="jobFeedback.elapsed"></span></div><p class="mt-1 leading-4" v-text="jobFeedback.detail"></p><button v-if="(activeJob.status==='failed'&&!activeJob.submission_ambiguous)||jobFeedback.stale" type="button" class="secondary-button mt-2 !px-2 text-xs" @click="retryJob">Retry this seam (no new upload)</button></div>
                            <p v-if="error" class="rounded-lg bg-red-50 p-3 text-xs text-red-700 dark:bg-red-950/30 dark:text-red-300" v-text="error"></p>
                            <p v-if="!sdkReady" class="rounded-lg bg-amber-50 p-3 text-xs text-amber-800">The shared Higgsfield work account is not connected. Ask an administrator to reconnect StylePress.</p>
                            <button type="button" class="primary-button flex w-full items-center justify-center gap-2" :disabled="!prepared || busy || !sdkReady" @click="generate"><span v-if="busy" class="icon-spinner animate-spin"></span><span v-else class="icon-magic-ai"></span>@{{ busy ? 'Preparing…' : 'Generate seam bridge' }}</button>
                            <p class="text-[11px] leading-4 text-gray-400">A credit estimate and explicit confirmation appear before any generation is submitted.</p>
                        </section>
                    </aside>

                    <main class="min-w-0 rounded-xl bg-white p-4 shadow-sm dark:bg-cherry-900">
                        <div class="mb-4 flex flex-wrap items-center justify-between gap-3 border-b border-gray-100 pb-4 dark:border-cherry-800"><div class="flex rounded-lg bg-gray-100 p-1 dark:bg-cherry-950"><button v-for="item in previewTabs" :key="item.key" type="button" class="rounded-md px-3 py-2 text-xs font-medium" :class="previewTab === item.key ? 'bg-white text-gray-900 shadow-sm dark:bg-cherry-800 dark:text-white' : 'text-gray-500'" @click="previewTab=item.key" v-text="item.label"></button></div><p class="text-xs text-gray-500" v-text="previewMeta"></p></div>
                        <div class="grid min-h-[520px] place-items-center overflow-hidden rounded-xl bg-gray-100 p-3 dark:bg-cherry-950">
                            <img v-if="activePreview" :src="activePreview" :alt="previewTab" class="max-h-[68vh] max-w-full rounded-lg object-contain shadow-lg">
                            <div v-else class="max-w-md text-center"><span class="icon-image text-5xl text-gray-300 dark:text-cherry-700"></span><p class="mt-4 font-semibold text-gray-700 dark:text-gray-200">Choose a panorama to begin</p><p class="mt-2 text-sm leading-6 text-gray-500">Normalization, edge extraction, reinsertion, wrap preview, and export stay in your browser.</p></div>
                        </div>
                        <div v-if="finalPreview" class="mt-4 flex flex-wrap items-center gap-2"><select v-model.number="exportWidth" class="rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm dark:border-cherry-800 dark:bg-cherry-950"><option v-for="option in exportOptions" :key="option.value" :value="option.value" v-text="option.label"></option></select><button class="secondary-button" @click="download('image/png')">Export PNG</button><button class="secondary-button" @click="download('image/webp')">Export WebP</button><button v-if="canCreateAssets && activeJob" class="primary-button" :disabled="busy" @click="saveToDam">Save to DAM</button></div>
                    </main>

                    <aside class="rounded-xl bg-white p-4 shadow-sm dark:bg-cherry-900 xl:sticky xl:top-4 xl:h-[calc(100vh-128px)] xl:overflow-y-auto"><div class="flex items-center justify-between"><p class="text-xs font-semibold uppercase tracking-wide text-gray-500">Recent seams</p><button class="text-xs font-medium text-primary-600" @click="loadHistory">Refresh</button></div>
                        <div v-if="history.length" class="mt-3 space-y-2"><button v-for="job in history" :key="job.id" type="button" class="w-full rounded-lg border border-gray-200 p-3 text-left transition hover:border-primary-400 dark:border-cherry-800" @click="selectJob(job)"><div class="flex items-center justify-between gap-2"><span class="text-xs font-semibold" v-text="modelLabel(job.model)"></span><span class="rounded-full bg-gray-100 px-2 py-0.5 text-[10px] uppercase dark:bg-cherry-950" v-text="job.status"></span></div><p class="mt-1 text-[11px] text-gray-500">@{{ job.width }}×@{{ job.height }} · @{{ job.bridge_ratio }} · band @{{ job.repair_width }}px</p><p v-if="job.error" class="mt-1 line-clamp-2 text-[11px] text-red-500" v-text="job.error"></p></button></div>
                        <p v-else class="mt-4 text-sm text-gray-500">No seam repairs yet.</p>
                    </aside>
                </div>
            </div>
        </script>

        <script type="module">
            import { preparePanorama, composeBridgeCanvasPlan, reinsertGeneratedBridge, createWrapPreview, createWrapComparison, scalePanorama, resolveGenerationSettings, resolveExportOptions, describeProviderOutput, checkUploadSize } from @json(route('sphereseam.script'));
            const image = (src, cors=false) => new Promise((resolve,reject)=>{const el=new Image();if(cors)el.crossOrigin='anonymous';el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('The image could not be loaded.'));el.src=src;});
            const blob = (canvas,type='image/png',quality=.95) => new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('The browser could not encode this panorama.')),type,quality));
            {{-- Lossless WebP: identical pixels to PNG, materially fewer bytes, and the difference
                 between an 8192x4096 panorama fitting inside post_max_size and PHP dropping the body.
                 quality 1 is lossless in Chromium; any browser that will not encode WebP falls back
                 to PNG rather than failing the save. The seam bridge deliberately stays PNG — that is
                 the format the paid provider runs were proven on. --}}
            const losslessBlob = async canvas => { try { const webp = await blob(canvas,'image/webp',1); if (webp && webp.type === 'image/webp') return webp; } catch (error) { /* fall through to PNG */ } return blob(canvas); };
            const extensionFor = value => value && value.type === 'image/webp' ? 'webp' : 'png';
            const objectUrl = async canvas => URL.createObjectURL(await blob(canvas));

            app.component('v-sphere-seam', {
                template: '#v-sphere-seam-template',
                data(){return{sourceName:'',sourceUrl:null,sourceAssetId:null,normalization:'squeeze',fill:'edge',repair:'wide',customRepairWidth:172,model:'gpt_image_2_5',ratio:'1:1',quality:'auto',resolution:'auto',scene:'',prepared:false,normalizationLabel:'',normalizedPreview:null,bridgePreview:null,guidePreview:null,finalPreview:null,wrapPreview:null,comparePreview:null,previewTab:'normalized',previewTabs:[{key:'normalized',label:'Normalized 2:1'},{key:'bridge',label:'Bridge input'},{key:'guide',label:'Sent to Higgsfield'},{key:'final',label:'Final panorama'},{key:'wrap',label:'Wrap check'},{key:'compare',label:'Wrap before / after'}],history:[],activeJob:null,busy:false,error:null,now:Date.now(),exportWidth:4096,preparedMeta:null,pollFailures:0,sdkReady:@json($sdkReady),canCreateAssets:@json($canCreateAssets),uploadLimits:@json($uploadLimits)}},
                {{-- preparedMeta carries every reactive fact about the prepared panorama. Until
                     2026-09-16 these computeds read `this._prepared`, a plain instance property, which
                     is not reactive in Vue 3.5: they were evaluated once and never again, so the Auto
                     resolution tier could stay pinned to a stale value and preparedWidth fell back to
                     4096 — both halves of the "saving at lower resolution" report. The canvases stay
                     on `this._prepared`, deliberately outside reactivity: they are tens of megabytes
                     of pixel buffers and deep-reactifying them would be ruinous. --}}
                computed:{activePreview(){return({normalized:this.normalizedPreview,bridge:this.bridgePreview,guide:this.guidePreview,final:this.finalPreview,wrap:this.wrapPreview,compare:this.comparePreview})[this.previewTab]||null},preparedWidth(){return this.preparedMeta?.panoramaWidth||0},previewMeta(){if(!this.preparedMeta)return'';return `${this.preparedMeta.panoramaWidth}×${this.preparedMeta.panoramaHeight} · exact 2:1`},
                    exportOptions(){return resolveExportOptions(this.preparedWidth)},
                    // Auto quality/resolution derive from the bridge that is actually sent; explicit choices pass through.
                    resolvedSettings(){const size=this.preparedMeta?{width:this.preparedMeta.bridgeWidth,height:this.preparedMeta.bridgeHeight}:{width:0,height:0};return resolveGenerationSettings(size,this.quality,this.resolution)},
                    resolvedSettingsLabel(){if(!this.preparedMeta)return'';const s=this.resolvedSettings;const auto=[this.quality==='auto'?`quality ${s.quality}`:null,this.resolution==='auto'?`${s.resolution.toUpperCase()}`:null].filter(Boolean);return auto.length?`Auto for this ${this.preparedMeta.bridgeWidth}×${this.preparedMeta.bridgeHeight} bridge: ${auto.join(', ')}.`:''},
                    // What the chosen tier actually buys: the provider result is scaled into the local
                    // bridge, so anything the tier does not cover is an upscale of paid-for pixels.
                    providerOutputLabel(){if(!this.preparedMeta)return'';return describeProviderOutput({width:this.preparedMeta.bridgeWidth,height:this.preparedMeta.bridgeHeight},this.resolvedSettings.resolution)?.label||''},
                    // Live progress for the selected seam: state, plain-language hint, elapsed time, stale warning.
                    jobFeedback(){const job=this.activeJob;if(!job)return null;const started=Date.parse(job.created_at||'')||this.now;const secs=Math.max(0,Math.round((this.now-started)/1000));const elapsed=secs<60?`${secs}s`:`${Math.floor(secs/60)}m ${secs%60}s`;const stale=job.status==='queued'&&secs>120;const map={queued:{title:stale?'Nothing has picked this up yet':'Queued on the shared work account',detail:stale?'No worker has taken this seam for over 2 minutes. Retry re-queues it without a new upload or charge; if it stalls again, the StylePress worker is down.':'Waiting for the StylePress worker to pick this up. Usually a few seconds.',busy:!stale,tone:'border-amber-200 bg-amber-50 text-amber-900 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200'},generating:{title:'Generating on Higgsfield',detail:'GPT Image is painting the repair band. Typically 30–120 s at 2K, longer at 4K. This panel updates every 3 s.',busy:true,tone:'border-primary-200 bg-primary-50 text-primary-900 dark:border-primary-900 dark:bg-primary-950/30 dark:text-primary-200'},completed:{title:'Seam bridge ready',detail:'Composed locally. See Final panorama and Wrap before / after, then export or save to DAM.',busy:false,tone:'border-green-200 bg-green-50 text-green-900 dark:border-green-900 dark:bg-green-950/30 dark:text-green-200'},failed:{title:'Generation failed',detail:job.error||'Higgsfield did not return a seam bridge.',busy:false,tone:'border-red-200 bg-red-50 text-red-800 dark:border-red-900 dark:bg-red-950/30 dark:text-red-300'}};return{...(map[job.status]||map.queued),stale,elapsed:['completed','failed'].includes(job.status)?'':elapsed}}},
                watch:{normalization(){this.rebuild()},fill(){this.rebuild()},repair(){this.rebuild()},customRepairWidth(){if(this.repair==='custom')this.rebuild()},ratio(){this.rebuild()},model(value){if(value==='gpt_image_2'&&this.ratio==='16:27')this.ratio='9:16'}},
                mounted(){this.loadHistory().then(()=>{const live=this.history.find(job=>['queued','generating'].includes(job.status));if(live)this.selectJob(live)});this._tick=setInterval(()=>{this.now=Date.now()},1000)},
                beforeUnmount(){this.clearUrls();if(this.sourceUrl)URL.revokeObjectURL(this.sourceUrl);clearInterval(this._poll);clearInterval(this._tick)},
                methods:{
                    async chooseFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>32*1024*1024){this.error='Choose a JPG, PNG, or WebP under 32 MB.';return}if(this.sourceUrl?.startsWith('blob:'))URL.revokeObjectURL(this.sourceUrl);this.sourceUrl=URL.createObjectURL(file);this.sourceName=file.name;this._sourceImage=await image(this.sourceUrl);this._sourceImageAssetId=null;await this.rebuild()},
                    openDamPicker(){this.$emitter.emit('dam-asset-picker:open',{ids:[],onAssign:ids=>this.resolveDamAsset(ids)})},
                    {{-- The DAM id travels with the image it identifies (_sourceImageAssetId) and is published as sourceAssetId only by rebuild(), in the same tick as the prepared pixels. A load or preparation that fails therefore leaves the previous id and pixels paired, and a later settings rebuild re-derives the id from whichever image produced the pixels. --}}
                    async resolveDamAsset(ids){try{const data=await this.request(@json($assetResolveUrl),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:Array.from(ids||[]).slice(0,1)})});if(!data.item)return;this.sourceUrl=data.item.source_url;this.sourceName=data.item.name;if(data.item.prompt&&!this.scene.trim())this.scene=data.item.prompt;this._sourceImage=await image(this.sourceUrl);this._sourceImageAssetId=data.item.id;await this.rebuild()}catch(error){this.error=error.message}},
                    clearUrls(){for(const key of ['normalizedPreview','bridgePreview','guidePreview','finalPreview','wrapPreview','comparePreview']){if(this[key]?.startsWith('blob:'))URL.revokeObjectURL(this[key]);this[key]=null}},
                    async rebuild(){if(!this._sourceImage)return;try{this.error=null;const result=preparePanorama(this._sourceImage,{normalization:this.normalization,fill:this.fill,repair:this.repair,ratio:this.ratio,customRepairWidth:this.customRepairWidth});this._prepared=result;const bp0=result.bridgePlan.bridge;this.preparedMeta={panoramaWidth:result.panorama.width,panoramaHeight:result.panorama.height,bridgeWidth:bp0.width,bridgeHeight:bp0.height,repairFraction:bp0.repair.fraction};this.sourceAssetId=this._sourceImageAssetId??null;this.prepared=true;this.finalPreview=null;this.wrapPreview=null;this.comparePreview=null;this.normalizedPreview=await objectUrl(result.panorama);this.bridgePreview=await objectUrl(result.bridge);this.guidePreview=await objectUrl(result.bridgeInput);const n=result.normalization,b=result.bridgePlan.bridge;this.normalizationLabel=!n.changed?`${n.target.width}×${n.target.height}; already exact 2:1.`:n.mode==='pad'?`${n.source.width}×${n.source.height} → ${n.target.width}×${n.target.height}; padded ${n.horizontalPadding}px horizontally and ${n.verticalPadding}px vertically.`:`${n.source.width}×${n.source.height} → ${n.target.width}×${n.target.height}; squeezed ${Math.round((1-Math.min(n.horizontalScale,n.verticalScale))*100)}% along the ${n.horizontalScale<1?'horizontal':'vertical'} axis, nothing cropped.`;this.normalizationLabel+=` Seam bridge ${b.width}×${b.height} (${b.left.width}+${b.right.width} px from the panorama edges); repair band ${b.repair.width}px, locked ${b.lockedLeft.width}px each side.`;this.exportWidth=result.panorama.width;this.previewTab='normalized'}catch(error){this.error=error.message}},
                    async request(url,options={}){const response=await fetch(url,{headers:{'Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token()),...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat()[0]||`Request failed (${response.status})`);return data},
                    settings(){const resolved=this.resolvedSettings;return{model:this.model,bridge_ratio:this.ratio,quality:resolved.quality,resolution:resolved.resolution,scene_description:this.scene,repair_fraction:this.preparedMeta?this.preparedMeta.repairFraction.toFixed(3):'0.400'}},
                    async estimate(settings=this.settings()){return this.request(@json($estimateUrl),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(settings)})},
                    {{-- Everything one submission sends is snapshotted at the click, before the first await. The DAM picker and the settings stay live while it runs, so re-reading _prepared, sourceAssetId or settings() after an await could pair one source's id and panorama with another's bridge, and the user would pay for a wrong generation. The estimate is taken from the same snapshot, so the confirmed cost matches what is submitted. --}}
                    async generate(){if(!this._prepared)return;const prepared=this._prepared,sourceAssetId=this.sourceAssetId,settings=this.settings();this.busy=true;this.error=null;try{const estimate=await this.estimate(settings);const credits=estimate.estimate?.credits??estimate.estimate?.cost;const message=credits==null?'This will submit one paid Higgsfield seam-bridge generation. Continue?':`This seam bridge is estimated at ${credits} credits. Continue?`;if(!window.confirm(message))return;const form=new FormData();Object.entries(settings).forEach(([key,value])=>form.append(key,String(value)));form.append('confirmed','1');if(sourceAssetId)form.append('source_asset_id',String(sourceAssetId));const bp=prepared.bridgePlan.bridge;form.append('strip_width',String(bp.left.width));form.append('repair_width',String(bp.repair.width));form.append('feather_width',String(Math.max(6,Math.round(bp.repair.width*.2))));form.append('normalization_mode',prepared.normalization.mode);const normalizedBlob=await losslessBlob(prepared.panorama),bridgeBlob=await blob(prepared.bridgeInput);
                        {{-- Checked here, against the server's own ceilings, because PHP discards a body over
                             post_max_size before Laravel ever runs: the old failure surfaced as "The panorama
                             field is required", naming neither the size nor the limit. --}}
                        for(const [value,limit,label] of [[normalizedBlob,this.uploadLimits.normalized,'normalized panorama'],[bridgeBlob,this.uploadLimits.bridge,'seam bridge']]){const check=checkUploadSize(value.size,limit,label);if(!check.ok){this.error=check.message;return}}
                        form.append('normalized',normalizedBlob,`normalized.${extensionFor(normalizedBlob)}`);form.append('bridge',bridgeBlob,'bridge.png');const data=await this.request(@json($generateUrl),{method:'POST',body:form});this.activeJob=data.generation;this.history=[data.generation,...this.history.filter(item=>item.id!==data.generation.id)];this.poll(data.generation.id)}catch(error){this.error=error.message}finally{this.busy=false}},
                    {{-- One failed status call used to clear the interval for good: a single blip during a
                         120 s generation left the panel frozen on "Generating" with no way back except a
                         page reload. Transient failures now back off (3 s doubling to 30 s) for up to
                         MAX_POLL_FAILURES consecutive attempts before the error is surfaced, and any
                         later user action — Refresh, selecting the seam, Retry — restarts polling. --}}
                    poll(id){clearInterval(this._poll);this.pollFailures=0;const tick=async()=>{try{const data=await this.request(this.url(@json($statusUrl),id));this.pollFailures=0;this.upsert(data.generation);if(['completed','failed'].includes(data.generation.status)){clearInterval(this._poll);if(data.generation.status==='completed')await this.selectJob(data.generation);return}this.schedulePoll(tick,3000)}catch(error){this.pollFailures+=1;if(this.pollFailures>=10){this.error=error.message;clearInterval(this._poll);return}this.schedulePoll(tick,Math.min(30000,3000*Math.pow(2,this.pollFailures-1)))}};this.schedulePoll(tick,3000)},
                    schedulePoll(tick,delay){clearInterval(this._poll);this._poll=setTimeout(tick,delay)},
                    async loadHistory(){try{const data=await this.request(@json($historyUrl));this.history=data.items||[]}catch(error){this.error=error.message}},
                    upsert(job){this.history=[job,...this.history.filter(item=>item.id!==job.id)];this.activeJob=job},
                    url(template,id){return template.replace('__ID__',id)},
                    modelLabel(value){return value==='gpt_image_2_5'?'GPT Image 2.5':'GPT Image 2'},
                    async retryJob(){if(!this.activeJob)return;try{this.error=null;const data=await this.request(this.url(@json($retryUrl),this.activeJob.id),{method:'POST'});this.upsert(data.generation);this.poll(data.generation.id)}catch(error){this.error=error.message}},
                    async selectJob(job){this.activeJob=job;if(['queued','generating'].includes(job.status)){this.poll(job.id);return}if(job.status!=='completed'||!job.bridge_result_url)return;try{this.busy=true;this.error=null;const [panorama,bridge]=await Promise.all([image(job.normalized_url),image(job.bridge_result_url,true)]);const holder=document.createElement('canvas');holder.width=panorama.naturalWidth;holder.height=panorama.naturalHeight;holder.getContext('2d').drawImage(panorama,0,0);const plan=composeBridgeCanvasPlan({width:holder.width,height:holder.height},'custom',job.bridge_ratio,job.repair_width);const final=reinsertGeneratedBridge(holder,bridge,plan,{featherWidth:job.feather_width});this._final=final;this.finalPreview=await objectUrl(final);this.wrapPreview=await objectUrl(createWrapPreview(final));this.comparePreview=await objectUrl(createWrapComparison(holder,final));
                        {{-- Derived from the recomposed pixels, not from job.width, so the export select
                             offers this panorama's true size and defaults to it. Without this the select
                             fell back to 4096 and the first click silently downscaled the export. --}}
                        this.preparedMeta={panoramaWidth:holder.width,panoramaHeight:holder.height,bridgeWidth:plan.bridge.width,bridgeHeight:plan.bridge.height,repairFraction:plan.bridge.repair.fraction};this.exportWidth=holder.width;this.previewTab='compare'}catch(error){this.error=`Could not compose this saved seam locally: ${error.message}`}finally{this.busy=false}},
                    async download(type){if(!this._final)return;const output=scalePanorama(this._final,this.exportWidth);const href=URL.createObjectURL(await blob(output,type));const a=document.createElement('a');a.href=href;a.download=`sphere-seam-${output.width}x${output.height}.${type==='image/webp'?'webp':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000)},
                    async saveToDam(){if(this.busy||!this._final||!this.activeJob)return;try{this.busy=true;this.error=null;const output=scalePanorama(this._final,this.exportWidth);const panorama=await losslessBlob(output);const check=checkUploadSize(panorama.size,this.uploadLimits.import,'exported panorama');if(!check.ok){this.error=check.message;return}const form=new FormData();form.append('panorama',panorama,`sphere-seam.${extensionFor(panorama)}`);const data=await this.request(this.url(@json($importUrl),this.activeJob.id),{method:'POST',body:form});this.activeJob.dam_asset_id=data.asset.id;window.location.href=data.asset.url}catch(error){this.error=error.message}finally{this.busy=false}},
                }
            });
        </script>
    @endPushOnce
